<?php
declare(strict_types=1);
$currentPage = 'claims';
require_once __DIR__ . '/_bootstrap.php';
$db = get_db(); $isAdminSide = role_is_admin_side($role); $error = null; $success = null;
function claim_pill(string $status): string { $map = ['pending'=>['pill--amber','Pending'],'manual_review'=>['pill--blue','Manual Review'],'approved'=>['pill--green','Approved'],'rejected'=>['pill--red','Rejected']]; [$class,$label] = $map[$status] ?? ['pill--gray', ucfirst($status)]; return '<span class="pill '.$class.'">'.h($label).'</span>'; }
function claim_answer(?string $json): string { $values = json_decode((string) $json, true); return is_array($values) && isset($values[0]) ? (string) $values[0] : '—'; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf($_POST['csrf_token'] ?? null)) $error = 'Your session expired. Please try again.';
    else {
        $action = (string) ($_POST['action'] ?? ''); $claimId = filter_var($_POST['claim_id'] ?? null, FILTER_VALIDATE_INT);
        try {
            if ($action === 'file_claim' && !$isAdminSide) {
                $itemId = filter_var($_POST['found_item_id'] ?? null, FILTER_VALIDATE_INT); $answer = trim((string) ($_POST['answer'] ?? ''));
                if (!$itemId || $answer === '' || strlen($answer) > 1000) throw new InvalidArgumentException('Enter a valid identifying detail.');
                $db->beginTransaction();
                $existing = $db->prepare("SELECT COUNT(*) FROM claims WHERE found_item_id = ? AND status IN ('pending', 'manual_review', 'approved')"); $existing->execute([$itemId]);
                if ((int) $existing->fetchColumn() > 0) throw new RuntimeException('That item already has an active claim.');
                $lock = $db->prepare("UPDATE found_items SET status = 'pending_verification' WHERE id = ? AND status = 'unclaimed'"); $lock->execute([$itemId]);
                if ($lock->rowCount() !== 1) throw new RuntimeException('That item is no longer available to claim.');
                $stmt = $db->prepare("INSERT INTO claims (found_item_id, claimant_id, challenge_questions, claimant_answers, status) VALUES (?, ?, ?, ?, 'pending')"); $stmt->execute([$itemId, $user['id'], json_encode(['Describe an identifying detail about this item.']), json_encode([$answer])]); $db->commit(); log_audit((int) $user['id'], 'claim_filed', "found_item={$itemId}"); $success = 'Your claim was submitted for review.';
            } elseif (in_array($action, ['approve', 'reject'], true) && $isAdminSide && $claimId) {
                $db->beginTransaction();
                $stmt = $db->prepare("SELECT found_item_id FROM claims WHERE id = ? AND status IN ('pending', 'manual_review') FOR UPDATE"); $stmt->execute([$claimId]); $claim = $stmt->fetch();
                if (!$claim) throw new RuntimeException('This claim has already been reviewed.');
                $newStatus = $action === 'approve' ? 'approved' : 'rejected'; $itemStatus = $action === 'approve' ? 'claimed' : 'unclaimed';
                $stmt = $db->prepare("UPDATE claims SET status = ?, reviewed_by = ?, reviewed_at = NOW() WHERE id = ? AND status IN ('pending', 'manual_review')"); $stmt->execute([$newStatus, $user['id'], $claimId]);
                if ($stmt->rowCount() !== 1) throw new RuntimeException('Claim review could not be applied.');
                $stmt = $db->prepare('UPDATE found_items SET status = ? WHERE id = ?'); $stmt->execute([$itemStatus, $claim['found_item_id']]); if ($stmt->rowCount() !== 1) throw new RuntimeException('Related found item could not be updated.');
                $db->commit(); log_audit((int) $user['id'], 'claim_' . $newStatus, "claim={$claimId}"); $success = $action === 'approve' ? 'Claim approved.' : 'Claim rejected.';
            } elseif ($action === 'manual_review' && $isAdminSide && $claimId) {
                $stmt = $db->prepare("UPDATE claims SET status = 'manual_review' WHERE id = ? AND status = 'pending'"); $stmt->execute([$claimId]); if ($stmt->rowCount() !== 1) throw new RuntimeException('Claim is no longer pending.'); log_audit((int) $user['id'], 'claim_manual_review', "claim={$claimId}"); $success = 'Claim flagged for manual review.';
            }
        } catch (InvalidArgumentException | RuntimeException $e) { if ($db->inTransaction()) $db->rollBack(); $error = $e->getMessage(); } catch (Throwable $e) { if ($db->inTransaction()) $db->rollBack(); $error = 'The claim could not be processed. Please try again.'; }
    }
}
if ($isAdminSide) $claims = $db->query('SELECT c.*, f.item_name, f.category, f.location_found, u.full_name AS claimant_name FROM claims c JOIN found_items f ON f.id = c.found_item_id JOIN users u ON u.id = c.claimant_id ORDER BY c.created_at DESC')->fetchAll();
else { $browsable = $db->query("SELECT * FROM found_items WHERE status = 'unclaimed' ORDER BY created_at DESC")->fetchAll(); $stmt = $db->prepare('SELECT c.*, f.item_name, f.category, f.location_found FROM claims c JOIN found_items f ON f.id = c.found_item_id WHERE c.claimant_id = ? ORDER BY c.created_at DESC'); $stmt->execute([$user['id']]); $claims = $stmt->fetchAll(); }
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Claims — Retrieva</title><link rel="stylesheet" href="../assets/theme.css"><link rel="stylesheet" href="styles.css"></head><body data-page="<?= h($currentPage) ?>" data-role="<?= h($role) ?>"><?php include __DIR__ . '/components/sidebar.php'; ?><div class="main-col"><?php include __DIR__ . '/components/header.php'; ?><main class="page-content"><div class="page-header"><h1>Claims</h1><p><?= $isAdminSide ? 'Review claims and verify ownership.' : 'Browse unclaimed items and file a claim if one is yours.' ?></p></div><?php if ($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><?php if ($success): ?><div class="alert alert-success"><?= h($success) ?></div><?php endif; ?><div class="card"><div class="data-table-wrap"><table class="data-table"><thead><tr><?php if ($isAdminSide): ?><th>Item</th><th>Claimant</th><th>Answer</th><th>Submitted</th><th>Status</th><th>Actions</th><?php else: ?><th>Item</th><th>Category</th><th>Location</th><th>Date Found</th><th>Claim</th><?php endif; ?></tr></thead><tbody><?php if ($isAdminSide): ?><?php if (!$claims): ?><tr class="empty-row"><td colspan="6">No claims filed yet.</td></tr><?php endif; ?><?php foreach ($claims as $claim): ?><tr><td><strong><?= h($claim['item_name']) ?></strong><br><small><?= h($claim['category']) ?> · <?= h($claim['location_found']) ?></small></td><td><?= h($claim['claimant_name']) ?></td><td><?= h(claim_answer($claim['claimant_answers'])) ?></td><td><?= h(date('M j, Y', strtotime($claim['created_at']))) ?></td><td><?= claim_pill($claim['status']) ?></td><td><?php if (in_array($claim['status'], ['pending','manual_review'], true)): ?><div class="actions-cell"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="approve"><input type="hidden" name="claim_id" value="<?= (int) $claim['id'] ?>"><button class="btn btn-sm btn-success">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="reject"><input type="hidden" name="claim_id" value="<?= (int) $claim['id'] ?>"><button class="btn btn-sm btn-danger">Reject</button></form><?php if ($claim['status'] === 'pending'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="manual_review"><input type="hidden" name="claim_id" value="<?= (int) $claim['id'] ?>"><button class="btn btn-sm btn-gold">Flag</button></form><?php endif; ?></div><?php endif; ?></td></tr><?php endforeach; ?><?php else: ?><?php if (!$browsable): ?><tr class="empty-row"><td colspan="5">Nothing unclaimed right now.</td></tr><?php endif; ?><?php foreach ($browsable as $item): ?><tr><td><strong><?= h($item['item_name']) ?></strong></td><td><?= h($item['category']) ?></td><td><?= h($item['location_found']) ?></td><td><?= h(date('M j, Y', strtotime($item['date_found']))) ?></td><td><form method="post" class="claim-form"><?= csrf_field() ?><input type="hidden" name="action" value="file_claim"><input type="hidden" name="found_item_id" value="<?= (int) $item['id'] ?>"><input maxlength="1000" type="text" name="answer" placeholder="Identifying detail" required><button class="btn btn-sm btn-primary">Claim</button></form></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></div><?php if (!$isAdminSide): ?><div class="section-title">My Claims</div><div class="card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Answer</th><th>Submitted</th><th>Status</th></tr></thead><tbody><?php if (!$claims): ?><tr class="empty-row"><td colspan="4">You have not filed any claims.</td></tr><?php endif; ?><?php foreach ($claims as $claim): ?><tr><td><strong><?= h($claim['item_name']) ?></strong></td><td><?= h(claim_answer($claim['claimant_answers'])) ?></td><td><?= h(date('M j, Y', strtotime($claim['created_at']))) ?></td><td><?= claim_pill($claim['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?></main></div><script src="dashboard.js"></script></body></html>
